export const OLGA_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/olga-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getOlgaStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(OLGA_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
